// ── Perceptual Color Ramps ────────────────────────────────────────────
//
// 7-stop ramps per color, generated by mixing with black/white.
// Each stop has a defined semantic role:
//   50  = lightest fill (shape background)
//   100 = medium fill (badge bg, emphasis fill)
//   300 = heavy fill (active state, selected)
//   500 = base color (stroke, icons)
//   600 = darkened base (stroke emphasis, secondary text on light bg)
//   800 = text primary (labels, readable on both themes)
//   900 = text on light fills (darkest, max contrast)

export interface ColorRamp {
  50: string;
  100: string;
  300: string;
  500: string;
  600: string;
  800: string;
  900: string;
}

export type ColorStop = keyof ColorRamp;

/** Parse hex color to RGB components */
function hexToRgb(hex: string): [number, number, number] {
  const h = hex.replace('#', '');
  return [
    parseInt(h.substring(0, 2), 16),
    parseInt(h.substring(2, 4), 16),
    parseInt(h.substring(4, 6), 16),
  ];
}

/** Convert RGB to hex */
function rgbToHex(r: number, g: number, b: number): string {
  const clamp = (v: number) => Math.max(0, Math.min(255, Math.round(v)));
  return '#' + [clamp(r), clamp(g), clamp(b)].map(v => v.toString(16).padStart(2, '0')).join('');
}

/** Mix two colors. ratio=0 returns c1, ratio=1 returns c2 */
function mixColors(c1: [number, number, number], c2: [number, number, number], ratio: number): [number, number, number] {
  return [
    c1[0] + (c2[0] - c1[0]) * ratio,
    c1[1] + (c2[1] - c1[1]) * ratio,
    c1[2] + (c2[2] - c1[2]) * ratio,
  ];
}

/** Apply alpha to a color by mixing with a background color */
function applyAlphaOnBg(color: [number, number, number], alpha: number, bg: [number, number, number]): string {
  return rgbToHex(
    bg[0] + (color[0] - bg[0]) * alpha,
    bg[1] + (color[1] - bg[1]) * alpha,
    bg[2] + (color[2] - bg[2]) * alpha,
  );
}

// Cache for generated ramps
const _rampCache = new Map<string, ColorRamp>();

/**
 * Generate a 7-stop perceptual color ramp from a base hex color.
 *
 * Cinema theme (dark bg #0c0d14): light stops mix color with dark bg at low alpha
 * Light theme (beige bg #f3ede4): light stops mix color with light bg, dark stops darken the color
 */
export function generateColorRamp(hex: string, theme?: 'cinema' | 'light'): ColorRamp {
  const t = theme ?? _activeTheme;
  const cacheKey = `${hex}:${t}`;
  const cached = _rampCache.get(cacheKey);
  if (cached) return cached;

  const base = hexToRgb(hex);
  const black: [number, number, number] = [0, 0, 0];

  let ramp: ColorRamp;

  if (t === 'light') {
    // Light theme: fills are color mixed onto beige, text darkens toward black
    const bg: [number, number, number] = [243, 237, 228]; // #f3ede4 (light bg)
    const darkBase = mixColors(base, black, 0.35); // darken base for text readability

    ramp = {
      50: applyAlphaOnBg(base, 0.15, bg),          // very light fill
      100: applyAlphaOnBg(base, 0.25, bg),          // medium fill
      300: applyAlphaOnBg(base, 0.40, bg),          // heavy fill
      500: rgbToHex(...mixColors(base, black, 0.20)), // darkened base for strokes
      600: rgbToHex(...mixColors(base, black, 0.30)), // darker for emphasis
      800: rgbToHex(...darkBase),                    // dark text
      900: rgbToHex(...mixColors(base, black, 0.50)), // darkest text
    };
  } else {
    // Cinema theme: fills are transparent-style on dark bg, strokes/text are bright
    const bg: [number, number, number] = [12, 13, 20]; // #0c0d14 (dark bg)

    ramp = {
      50: applyAlphaOnBg(base, 0.12, bg),          // subtle fill
      100: applyAlphaOnBg(base, 0.20, bg),          // medium fill
      300: applyAlphaOnBg(base, 0.35, bg),          // heavy fill
      500: hex,                                      // full base (bright on dark)
      600: hex,                                      // same (already bright enough)
      800: hex,                                      // text is full color on dark
      900: rgbToHex(...mixColors(base, [255, 255, 255], 0.15)), // slightly lighter
    };
  }

  _rampCache.set(cacheKey, ramp);
  return ramp;
}

/** Clear ramp cache (call when theme changes) */
export function clearColorRampCache(): void {
  _rampCache.clear();
}

